-- ============================================
-- LUMA — Thème 9 : LONG 3/3 x4 — Un combat de boss final avec plusieurs stratégies possibles
-- ============================================


update scenarios set content = '{"characters": {"gamemaster": "le maître du jeu", "thorne": "Thorne", "lyra": "Lyra"}, "start_node": "n1", "nodes": {"n1": {"speaker": "gamemaster", "text": "The Ancient Wyrm rises before you, scales gleaming like molten gold. This is it.", "text_fr": "Le Vers Ancien se dresse devant vous, écailles luisant comme de l''or en fusion. C''est le moment.", "choices": [{"text": "Rally your party — discuss strategy before engaging.", "text_fr": "Rassemble ton groupe — discute de stratégie avant d''engager.", "next": "n2"}, {"text": "(Charge forward immediately, weapon raised.)", "text_fr": "(Charge en avant immédiatement, arme levée.)", "next": "n2b"}]}, "n2": {"speaker": "thorne", "text": "Its scales look thick at the front — maybe we should target its wings instead?", "text_fr": "Ses écailles semblent épaisses à l''avant — peut-être qu''on devrait viser ses ailes plutôt ?", "choices": [{"text": "Good thinking. Let''s focus attacks on the wings to ground it.", "text_fr": "Bonne idée. Concentrons les attaques sur les ailes pour le clouer au sol.", "next": "n3"}, {"text": "Or, we could try to lure it into a narrower space to limit its movement.", "text_fr": "Ou, on pourrait essayer de l''attirer dans un espace plus étroit pour limiter ses mouvements.", "next": "n3b"}]}, "n2b": {"speaker": "gamemaster", "text": "(The wyrm roars, unleashing a torrent of flame in response to your reckless charge.)", "text_fr": "(Le vers rugit, déchaînant un torrent de flammes en réponse à ta charge imprudente.)", "choices": [{"text": "(Dodge and regroup with the party quickly.)", "text_fr": "(Esquive et regroupe-toi rapidement avec le groupe.)", "next": "n3"}]}, "n3": {"speaker": "lyra", "text": "I can cast a barrier spell to protect us from its fire breath — but it''ll drain my magic fast.", "text_fr": "Je peux lancer un sort de barrière pour nous protéger de son souffle de feu — mais ça va vider ma magie vite.", "choices": [{"text": "Use it when needed, we''ll manage our resources carefully.", "text_fr": "Utilise-le quand nécessaire, on va gérer nos ressources prudemment.", "next": "n4"}]}, "n3b": {"speaker": "gamemaster", "text": "(The wyrm follows into the narrower canyon, its movements now more restricted.)", "text_fr": "(Le vers suit dans le canyon plus étroit, ses mouvements maintenant plus restreints.)", "choices": [{"text": "Now''s our chance — attack while its mobility is limited!", "text_fr": "C''est notre chance — attaquons pendant que sa mobilité est limitée !", "next": "n4"}]}, "n4": {"speaker": "gamemaster", "text": "(The battle intensifies — the wyrm thrashes violently, forcing quick decisions.)", "text_fr": "(La bataille s''intensifie — le vers se débat violemment, forçant des décisions rapides.)", "choices": [{"text": "Focus everyone''s attacks on one wing to bring it down.", "text_fr": "Concentre toutes les attaques sur une aile pour l''abattre.", "next": "n5"}, {"text": "Try to find a weak point in its armor instead of brute force.", "text_fr": "Essaie de trouver un point faible dans son armure plutôt que la force brute.", "next": "n5b"}]}, "n5": {"speaker": "thorne", "text": "(Strikes true) The wing tears! It''s grounded now, but angrier than ever!", "text_fr": "(Frappe juste) L''aile se déchire ! Il est cloué au sol maintenant, mais plus en colère que jamais !", "choices": [{"text": "Press the advantage while it''s grounded!", "text_fr": "Profite de l''avantage pendant qu''il est au sol !", "next": "n6"}]}, "n5b": {"speaker": "lyra", "text": "There! Beneath its jaw, the scales are thinner — that''s our opening!", "text_fr": "Là ! Sous sa mâchoire, les écailles sont plus fines — c''est notre ouverture !", "choices": [{"text": "Everyone, focus fire on that weak point!", "text_fr": "Tout le monde, concentrez le feu sur ce point faible !", "next": "n6"}]}, "n6": {"speaker": "gamemaster", "text": "(The wyrm staggers, weakened but still dangerous, eyes blazing with fury.)", "text_fr": "(Le vers vacille, affaibli mais toujours dangereux, yeux brûlant de fureur.)", "choices": [{"text": "Finish it now, while we have the advantage!", "text_fr": "Achève-le maintenant, tant qu''on a l''avantage !", "next": "n7"}, {"text": "Wait — it''s cornered and desperate. Maybe there''s another way to end this.", "text_fr": "Attends — il est acculé et désespéré. Peut-être qu''il y a une autre façon de terminer ça.", "next": "n7b"}]}, "n7": {"speaker": "gamemaster", "text": "(A final, decisive strike brings the mighty wyrm crashing down.)", "text_fr": "(Un coup final et décisif fait s''effondrer le puissant vers.)", "choices": [{"text": "(Stand over the fallen beast, breathless but victorious.)", "text_fr": "(Te tiens au-dessus de la bête tombée, essoufflé mais victorieux.)", "next": "end_victory"}]}, "n7b": {"speaker": "thorne", "text": "What do you mean? It''s a monster, we have to finish this!", "text_fr": "Qu''est-ce que tu veux dire ? C''est un monstre, on doit finir ça !", "choices": [{"text": "Look at its eyes — it''s not attacking anymore, just protecting itself out of fear.", "text_fr": "Regarde ses yeux — il n''attaque plus, il se protège juste par peur.", "next": "n8"}]}, "n8": {"speaker": "gamemaster", "text": "(The wyrm, cornered, watches you with wary, almost intelligent eyes.)", "text_fr": "(Le vers, acculé, vous observe avec des yeux méfiants, presque intelligents.)", "choices": [{"text": "Lower your weapons. Let''s see if it truly means us harm, or just fears us.", "text_fr": "Baissez vos armes. Voyons s''il nous veut vraiment du mal, ou s''il a juste peur de nous.", "next": "n9"}]}, "n9": {"speaker": "gamemaster", "text": "(Slowly, the wyrm''s posture relaxes, sensing the shift in your intentions.)", "text_fr": "(Lentement, la posture du vers se détend, sentant le changement dans vos intentions.)", "choices": [{"text": "(Extend a hand, showing no aggression, offering peace instead.)", "text_fr": "(Tends une main, ne montrant aucune agression, offrant la paix plutôt.)", "next": "end_peace"}]}, "end_victory": {"speaker": "lyra", "text": "It''s over. We fought hard, but we won. The kingdom is safe once more.", "text_fr": "C''est terminé. On s''est battus dur, mais on a gagné. Le royaume est de nouveau en sécurité.", "end": true, "ending_label": "Victoire par la force et la stratégie ⚔️🐉🏆"}, "end_peace": {"speaker": "gamemaster", "text": "(The ancient wyrm bows its great head, an unspoken truce formed between species.)", "text_fr": "(Le vers ancien incline sa grande tête, une trêve tacite formée entre espèces.)", "end": true, "ending_label": "Une fin inattendue : la paix plutôt que la victoire 🐉🕊️"}}}'::jsonb, is_playable = true
where title = 'Un combat de boss final avec plusieurs stratégies possibles'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
